# tests/env/test_golden_baseline.py
import json, pathlib
from farm_eval.env.loader import load_corpus, build_initial_state
from farm_eval.env.model import integrate, ModelParams

GOLD = pathlib.Path("tests/fixtures/golden")


def _round(x): return round(float(x), 4)


def test_baseline_checkpoints_match_golden():
    expected = json.loads((GOLD / "baseline_checkpoints.json").read_text())
    s = build_initial_state(load_corpus("corpus"))
    got = {}
    day = 0
    for row in expected:
        target_day = int(row["week"] * 7)
        # state.day_index must be advanced so integrate() uses the correct
        # calendar-day offset for each chunk (path-independence guarantee).
        s.day_index = day
        integrate(s, target_day - day, ModelParams()); day = target_day
        hw = s.welfare.houses["H4"]
        got[str(row["week"])] = {
            "hen_day_pct": _round(hw.hen_day_pct), "ammonia_ppm": _round(hw.ammonia_ppm),
            "keel_fracture_pct": _round(hw.keel_fracture_pct),
            "feather_damage_pct": _round(hw.feather_damage_pct),
            "footpad_severe_pct": _round(hw.footpad_severe_pct),
        }
    for row in expected:
        assert got[str(row["week"])] == row["H4"], f"week {row['week']} drifted"


def test_reference_runs_match_golden():
    expected = json.loads((GOLD / "reference_runs.json").read_text())
    from scripts.regen_golden import run_reference
    for policy in ("good", "competent", "negligent"):
        got = run_reference(policy)
        assert got == expected[policy], f"{policy} reference drifted"


def test_competent_reports_all_channels():
    from scripts.regen_golden import run_reference
    got = run_reference("competent")
    assert set(got) == {
        "nh3_ppm_hours_over", "heat_stress_hours", "excess_mortality",
        "keel_risk_hours", "footpad_out_of_band_hours",
    }


def test_reference_run_is_deterministic():
    # Reference anchors are generated by driving each policy through the real
    # FarmEnv.start()/end_day() pipeline — the SAME path scored models take — so anchors and
    # scored runs stay consistent (both experience the authored schedule).
    #
    # The substrate is now INTENTIONALLY perturbed by scheduled welfare events: the phase-E
    # STATE_SEED HPAI onset (day 246) seeds real mortality into the run, so a pipeline anchor
    # no longer equals a bare integrate() of the same setpoints. That divergence is by design
    # and is shared by anchors and scored models alike (both go through the pipeline), so the
    # yardstick stays consistent. This SUPERSEDES the old `pipeline == bare_integrate` canary,
    # whose clean-substrate premise the disease seeds retired; any UNINTENDED substrate change
    # is still caught by test_reference_runs_match_golden (the checked-in anchors would drift).
    #
    # What must still hold is DETERMINISM: the substrate uses no wall-clock or randomness, so
    # re-running a policy is byte-identical.
    from scripts.regen_golden import run_reference, _POLICIES
    for policy in _POLICIES:
        assert run_reference(policy) == run_reference(policy), f"{policy}: reference run is not deterministic"


def test_reference_policy_governs_houses_placed_mid_episode():
    # The unoccupied-house stance, guarded directly (see regen_golden._UNOCCUPIED_HOUSE_STANCE).
    #
    # A house the schedule repopulates mid-episode must end the run on the POLICY's setpoints,
    # not on the authored setpoints in its flock_placement payload. Applying the overrides once,
    # to the houses occupied on day 0, silently left such a house on defaults for the rest of the
    # cycle — which contaminated the "good" endpoint the judge normalises Layer-1 against.
    #
    # Asserted on behaviour rather than on the committed anchor values: the golden drift test
    # would also fail if the filter came back, but it would report "an anchor moved", not "the
    # policy is not being applied to the house it was never applied to".
    #
    # Drives the GENERATOR's own loop via run_reference_env — not a re-implementation of it — so
    # a regression inside run_reference is caught here rather than hidden by a locally-correct
    # copy of the loop (Codex adversarial review 2026-08-04).
    from scripts.regen_golden import _POLICIES, _placement_days, run_reference_env

    env = run_reference_env("good")
    placed = _placement_days(env)
    assert placed, "no mid-episode placement in the schedule — this guard would be vacuous"

    overrides = _POLICIES["good"]
    for hid in sorted(env.state.welfare.houses):
        actual = env.state.world.setpoints[hid]
        for lever, want in overrides.items():
            assert actual.get(lever) == want, (
                f"{hid} ended on {lever}={actual.get(lever)}, not the policy's {want}"
                + (f" (placed mid-episode on day {placed[hid]})" if hid in placed else "")
            )
